// Ethernet_RS_FEC_apb checker (generated by scripts/apb/gen_apb.py; do not edit).
// Register model held as an array of words, updated from the APB pins and
// the core's outputs; it predicts PRDATA on every read, PSLVERR, PREADY, irq
// and every core input the wrapper drives. FC: every word read and written,
// every interrupt bit set / cleared / masked / raising irq, stream events,
// strobes, unmapped and misaligned accesses, back-to-back transfers.
`include "cov_macros.svh"
module Ethernet_RS_FEC_apb_sva (
  input logic PCLK, PRESETN, PSEL, PENABLE, PWRITE,
  input logic [11:0] PADDR,
  input logic [31:0] PWDATA,
  input logic [3:0] PSTRB,
  input logic [31:0] PRDATA,
  input logic PREADY, PSLVERR, irq,
  input logic  c_cfg_bypass_corr,
  input logic  c_cfg_bypass_ind,
  input logic [319:0] c_e_in_data,
  input logic  c_e_in_first,
  input logic [319:0] c_e_out_data,
  input logic  c_e_out_first,
  input logic [319:0] c_d_in_data,
  input logic  c_d_in_first,
  input logic [319:0] c_d_out_data,
  input logic  c_d_out_first,
  input logic  c_d_out_bad,
  input logic [3:0] c_st_nsym,
  input logic  c_e_in_valid,
  input logic  c_e_in_ready,
  input logic  c_e_out_valid,
  input logic  c_e_out_ready,
  input logic  c_d_in_valid,
  input logic  c_d_in_ready,
  input logic  c_d_out_valid,
  input logic  c_d_out_ready,
  input logic  c_ev_corr,
  input logic  c_ev_uncorr,
  input logic  c_ev_eresync,
  input logic  c_ev_dresync
);
  `COV_CLOCKING(PCLK, !PRESETN)
  wire        m_wr  = PSEL && PENABLE && PWRITE;
  wire        m_rd  = PSEL && PENABLE && !PWRITE;
  wire        m_map = PADDR[1:0] == 2'b00 && (PADDR >> 2) < 51;
  wire [9:0] m_idx = PADDR[11:2];
  wire [31:0] m_be  = {{8{PSTRB[3]}}, {8{PSTRB[2]}}, {8{PSTRB[1]}}, {8{PSTRB[0]}}};
  logic [31:0] m_w [0:50];          // model of every stored word
  logic [9:0] m_set;                // interrupt bits set this clock
  logic m_state_ENC_IN;          // full / valid pulse / available
  logic m_state_ENC_OUT;          // full / valid pulse / available
  logic m_state_DEC_IN;          // full / valid pulse / available
  logic m_state_DEC_OUT;          // full / valid pulse / available

  always_comb begin
    m_set = '0;
    if (c_ev_corr) m_set[0] = 1'b1;
    if (c_ev_uncorr) m_set[1] = 1'b1;
    if (c_ev_eresync) m_set[2] = 1'b1;
    if (c_ev_dresync) m_set[3] = 1'b1;
    if (m_state_ENC_IN && c_e_in_ready) m_set[4] = 1'b1;
    if (m_wr && m_map && (m_idx == 6 || m_idx == 7 || m_idx == 8 || m_idx == 9 || m_idx == 10 || m_idx == 11 || m_idx == 12 || m_idx == 13 || m_idx == 14 || m_idx == 15 || m_idx == 16) && m_state_ENC_IN) m_set[5] = 1'b1;
    if (c_e_out_valid && !m_state_ENC_OUT) m_set[6] = 1'b1;
    if (c_e_out_valid && m_state_ENC_OUT && (m_rd && m_map && m_idx == 27)) m_set[6] = 1'b1;
    if (m_state_DEC_IN && c_d_in_ready) m_set[7] = 1'b1;
    if (m_wr && m_map && (m_idx == 28 || m_idx == 29 || m_idx == 30 || m_idx == 31 || m_idx == 32 || m_idx == 33 || m_idx == 34 || m_idx == 35 || m_idx == 36 || m_idx == 37 || m_idx == 38) && m_state_DEC_IN) m_set[8] = 1'b1;
    if (c_d_out_valid && !m_state_DEC_OUT) m_set[9] = 1'b1;
    if (c_d_out_valid && m_state_DEC_OUT && (m_rd && m_map && m_idx == 49)) m_set[9] = 1'b1;
  end

  always_ff @(posedge PCLK or negedge PRESETN) begin
    if (!PRESETN) begin
      m_w[0] <= 32'h0;
      m_w[1] <= 32'h0;
      m_w[2] <= 32'h0;
      m_w[3] <= 32'h0;
      m_w[4] <= 32'h0;
      m_w[5] <= 32'h0;
      m_w[6] <= 32'h0;
      m_w[7] <= 32'h0;
      m_w[8] <= 32'h0;
      m_w[9] <= 32'h0;
      m_w[10] <= 32'h0;
      m_w[11] <= 32'h0;
      m_w[12] <= 32'h0;
      m_w[13] <= 32'h0;
      m_w[14] <= 32'h0;
      m_w[15] <= 32'h0;
      m_w[16] <= 32'h0;
      m_w[17] <= 32'h0;
      m_w[18] <= 32'h0;
      m_w[19] <= 32'h0;
      m_w[20] <= 32'h0;
      m_w[21] <= 32'h0;
      m_w[22] <= 32'h0;
      m_w[23] <= 32'h0;
      m_w[24] <= 32'h0;
      m_w[25] <= 32'h0;
      m_w[26] <= 32'h0;
      m_w[27] <= 32'h0;
      m_w[28] <= 32'h0;
      m_w[29] <= 32'h0;
      m_w[30] <= 32'h0;
      m_w[31] <= 32'h0;
      m_w[32] <= 32'h0;
      m_w[33] <= 32'h0;
      m_w[34] <= 32'h0;
      m_w[35] <= 32'h0;
      m_w[36] <= 32'h0;
      m_w[37] <= 32'h0;
      m_w[38] <= 32'h0;
      m_w[39] <= 32'h0;
      m_w[40] <= 32'h0;
      m_w[41] <= 32'h0;
      m_w[42] <= 32'h0;
      m_w[43] <= 32'h0;
      m_w[44] <= 32'h0;
      m_w[45] <= 32'h0;
      m_w[46] <= 32'h0;
      m_w[47] <= 32'h0;
      m_w[48] <= 32'h0;
      m_w[49] <= 32'h0;
      m_w[50] <= 32'h0;
      m_state_ENC_IN <= 0;
      m_state_ENC_OUT <= 0;
      m_state_DEC_IN <= 0;
      m_state_DEC_OUT <= 0;
    end else begin
      m_w[1] <= (m_w[1] & ~((m_wr && m_map && m_idx == 1) ? PWDATA & m_be : 0)) | 32'(m_set);
      if (m_wr && m_map && m_idx == 2) m_w[2] <= ((m_w[2] & ~m_be) | (PWDATA & m_be)) & 32'h3FF;
      if (m_wr && m_map && m_idx == 4) m_w[4] <= ((m_w[4] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 5) m_w[5] <= ((m_w[5] & ~m_be) | (PWDATA & m_be)) & 32'h3;
      if (m_wr && m_map && m_idx == 6 && !m_state_ENC_IN) m_w[6] <= ((m_w[6] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 7 && !m_state_ENC_IN) m_w[7] <= ((m_w[7] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 8 && !m_state_ENC_IN) m_w[8] <= ((m_w[8] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 9 && !m_state_ENC_IN) m_w[9] <= ((m_w[9] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 10 && !m_state_ENC_IN) m_w[10] <= ((m_w[10] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 11 && !m_state_ENC_IN) m_w[11] <= ((m_w[11] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 12 && !m_state_ENC_IN) m_w[12] <= ((m_w[12] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 13 && !m_state_ENC_IN) m_w[13] <= ((m_w[13] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 14 && !m_state_ENC_IN) m_w[14] <= ((m_w[14] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 15 && !m_state_ENC_IN) m_w[15] <= ((m_w[15] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 16 && !m_state_ENC_IN) m_w[16] <= ((m_w[16] & ~m_be) | (PWDATA & m_be)) & 32'h1;
      if (m_wr && m_map && m_idx == 16 && !m_state_ENC_IN) m_state_ENC_IN <= 1;
      if (m_state_ENC_IN && c_e_in_ready) m_state_ENC_IN <= 0;
      if (c_e_out_valid && (!m_state_ENC_OUT || (m_rd && m_map && m_idx == 27))) begin
        m_w[17] <= (32'(c_e_out_data[31:0]) << 0);
        m_w[18] <= (32'(c_e_out_data[63:32]) << 0);
        m_w[19] <= (32'(c_e_out_data[95:64]) << 0);
        m_w[20] <= (32'(c_e_out_data[127:96]) << 0);
        m_w[21] <= (32'(c_e_out_data[159:128]) << 0);
        m_w[22] <= (32'(c_e_out_data[191:160]) << 0);
        m_w[23] <= (32'(c_e_out_data[223:192]) << 0);
        m_w[24] <= (32'(c_e_out_data[255:224]) << 0);
        m_w[25] <= (32'(c_e_out_data[287:256]) << 0);
        m_w[26] <= (32'(c_e_out_data[319:288]) << 0);
        m_w[27] <= (32'(c_e_out_first) << 0);
        m_state_ENC_OUT <= 1;
      end else if ((m_rd && m_map && m_idx == 27)) m_state_ENC_OUT <= 0;
      if (m_wr && m_map && m_idx == 28 && !m_state_DEC_IN) m_w[28] <= ((m_w[28] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 29 && !m_state_DEC_IN) m_w[29] <= ((m_w[29] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 30 && !m_state_DEC_IN) m_w[30] <= ((m_w[30] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 31 && !m_state_DEC_IN) m_w[31] <= ((m_w[31] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 32 && !m_state_DEC_IN) m_w[32] <= ((m_w[32] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 33 && !m_state_DEC_IN) m_w[33] <= ((m_w[33] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 34 && !m_state_DEC_IN) m_w[34] <= ((m_w[34] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 35 && !m_state_DEC_IN) m_w[35] <= ((m_w[35] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 36 && !m_state_DEC_IN) m_w[36] <= ((m_w[36] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 37 && !m_state_DEC_IN) m_w[37] <= ((m_w[37] & ~m_be) | (PWDATA & m_be)) & 32'hFFFFFFFF;
      if (m_wr && m_map && m_idx == 38 && !m_state_DEC_IN) m_w[38] <= ((m_w[38] & ~m_be) | (PWDATA & m_be)) & 32'h1;
      if (m_wr && m_map && m_idx == 38 && !m_state_DEC_IN) m_state_DEC_IN <= 1;
      if (m_state_DEC_IN && c_d_in_ready) m_state_DEC_IN <= 0;
      if (c_d_out_valid && (!m_state_DEC_OUT || (m_rd && m_map && m_idx == 49))) begin
        m_w[39] <= (32'(c_d_out_data[31:0]) << 0);
        m_w[40] <= (32'(c_d_out_data[63:32]) << 0);
        m_w[41] <= (32'(c_d_out_data[95:64]) << 0);
        m_w[42] <= (32'(c_d_out_data[127:96]) << 0);
        m_w[43] <= (32'(c_d_out_data[159:128]) << 0);
        m_w[44] <= (32'(c_d_out_data[191:160]) << 0);
        m_w[45] <= (32'(c_d_out_data[223:192]) << 0);
        m_w[46] <= (32'(c_d_out_data[255:224]) << 0);
        m_w[47] <= (32'(c_d_out_data[287:256]) << 0);
        m_w[48] <= (32'(c_d_out_data[319:288]) << 0);
        m_w[49] <= (32'(c_d_out_first) << 0) | (32'(c_d_out_bad) << 1);
        m_state_DEC_OUT <= 1;
      end else if ((m_rd && m_map && m_idx == 49)) m_state_DEC_OUT <= 0;
    end
  end

  function automatic logic [31:0] m_read(input logic [9:0] i);
    case (i)
      0: return 32'h52530100;
      1: return m_w[1];
      2: return m_w[2];
      3: return 32'({m_state_DEC_OUT, m_state_DEC_IN, m_state_ENC_OUT, m_state_ENC_IN});
      4: return m_w[4];
      5: return m_w[5];
      6: return m_w[6];
      7: return m_w[7];
      8: return m_w[8];
      9: return m_w[9];
      10: return m_w[10];
      11: return m_w[11];
      12: return m_w[12];
      13: return m_w[13];
      14: return m_w[14];
      15: return m_w[15];
      16: return m_w[16];
      17: return m_w[17];
      18: return m_w[18];
      19: return m_w[19];
      20: return m_w[20];
      21: return m_w[21];
      22: return m_w[22];
      23: return m_w[23];
      24: return m_w[24];
      25: return m_w[25];
      26: return m_w[26];
      27: return m_w[27];
      28: return m_w[28];
      29: return m_w[29];
      30: return m_w[30];
      31: return m_w[31];
      32: return m_w[32];
      33: return m_w[33];
      34: return m_w[34];
      35: return m_w[35];
      36: return m_w[36];
      37: return m_w[37];
      38: return m_w[38];
      39: return m_w[39];
      40: return m_w[40];
      41: return m_w[41];
      42: return m_w[42];
      43: return m_w[43];
      44: return m_w[44];
      45: return m_w[45];
      46: return m_w[46];
      47: return m_w[47];
      48: return m_w[48];
      49: return m_w[49];
      50: return (32'(c_st_nsym) << 0);
      default: return 0;
    endcase
  endfunction

  // ---------------- assertions ----------------
  `SVA_INV(a_pready_zero_wait, PREADY == (PSEL && PENABLE))
  `SVA_IMP(a_pslverr_decode, PSEL && PENABLE, PSLVERR == !m_map)
  `SVA_IMP(a_read_data, m_rd && m_map, PRDATA == m_read(m_idx))
  `SVA_IMP(a_unmapped_read_zero, m_rd && !m_map, PRDATA == 0)
  `SVA_IMP(a_prdata_zero_outside_read, !m_rd, PRDATA == 0)
  `SVA_INV(a_irq_pin, irq == |(m_w[1][9:0] & m_w[2][9:0]))
  `SVA_INV(a_core_cfg_bypass_corr, c_cfg_bypass_corr == m_w[5][0:0])
  `SVA_INV(a_core_cfg_bypass_ind, c_cfg_bypass_ind == m_w[5][1:1])
  `SVA_INV(a_core_e_in_data_31_0, c_e_in_data[31:0] == m_w[6][31:0])
  `SVA_INV(a_core_e_in_data_63_32, c_e_in_data[63:32] == m_w[7][31:0])
  `SVA_INV(a_core_e_in_data_95_64, c_e_in_data[95:64] == m_w[8][31:0])
  `SVA_INV(a_core_e_in_data_127_96, c_e_in_data[127:96] == m_w[9][31:0])
  `SVA_INV(a_core_e_in_data_159_128, c_e_in_data[159:128] == m_w[10][31:0])
  `SVA_INV(a_core_e_in_data_191_160, c_e_in_data[191:160] == m_w[11][31:0])
  `SVA_INV(a_core_e_in_data_223_192, c_e_in_data[223:192] == m_w[12][31:0])
  `SVA_INV(a_core_e_in_data_255_224, c_e_in_data[255:224] == m_w[13][31:0])
  `SVA_INV(a_core_e_in_data_287_256, c_e_in_data[287:256] == m_w[14][31:0])
  `SVA_INV(a_core_e_in_data_319_288, c_e_in_data[319:288] == m_w[15][31:0])
  `SVA_INV(a_core_e_in_first, c_e_in_first == m_w[16][0:0])
  `SVA_INV(a_core_d_in_data_31_0, c_d_in_data[31:0] == m_w[28][31:0])
  `SVA_INV(a_core_d_in_data_63_32, c_d_in_data[63:32] == m_w[29][31:0])
  `SVA_INV(a_core_d_in_data_95_64, c_d_in_data[95:64] == m_w[30][31:0])
  `SVA_INV(a_core_d_in_data_127_96, c_d_in_data[127:96] == m_w[31][31:0])
  `SVA_INV(a_core_d_in_data_159_128, c_d_in_data[159:128] == m_w[32][31:0])
  `SVA_INV(a_core_d_in_data_191_160, c_d_in_data[191:160] == m_w[33][31:0])
  `SVA_INV(a_core_d_in_data_223_192, c_d_in_data[223:192] == m_w[34][31:0])
  `SVA_INV(a_core_d_in_data_255_224, c_d_in_data[255:224] == m_w[35][31:0])
  `SVA_INV(a_core_d_in_data_287_256, c_d_in_data[287:256] == m_w[36][31:0])
  `SVA_INV(a_core_d_in_data_319_288, c_d_in_data[319:288] == m_w[37][31:0])
  `SVA_INV(a_core_d_in_first, c_d_in_first == m_w[38][0:0])
  `SVA_INV(a_core_e_in_valid, c_e_in_valid == m_state_ENC_IN)
  `SVA_INV(a_core_e_out_ready, c_e_out_ready == (!m_state_ENC_OUT || (m_rd && m_map && m_idx == 27)))
  `SVA_INV(a_core_d_in_valid, c_d_in_valid == m_state_DEC_IN)
  `SVA_INV(a_core_d_out_ready, c_d_out_ready == (!m_state_DEC_OUT || (m_rd && m_map && m_idx == 49)))
  `SVA_RST(a_reset_values, !PRESETN, PRDATA == 0 && !irq && c_cfg_bypass_corr == 1'h0 && c_cfg_bypass_ind == 1'h0 && c_e_in_data[31:0] == 32'h0 && c_e_in_data[63:32] == 32'h0 && c_e_in_data[95:64] == 32'h0 && c_e_in_data[127:96] == 32'h0 && c_e_in_data[159:128] == 32'h0 && c_e_in_data[191:160] == 32'h0 && c_e_in_data[223:192] == 32'h0 && c_e_in_data[255:224] == 32'h0 && c_e_in_data[287:256] == 32'h0 && c_e_in_data[319:288] == 32'h0 && c_e_in_first == 1'h0 && c_d_in_data[31:0] == 32'h0 && c_d_in_data[63:32] == 32'h0 && c_d_in_data[95:64] == 32'h0 && c_d_in_data[127:96] == 32'h0 && c_d_in_data[159:128] == 32'h0 && c_d_in_data[191:160] == 32'h0 && c_d_in_data[223:192] == 32'h0 && c_d_in_data[255:224] == 32'h0 && c_d_in_data[287:256] == 32'h0 && c_d_in_data[319:288] == 32'h0 && c_d_in_first == 1'h0 && !c_e_in_valid && c_e_out_ready && !c_d_in_valid && c_d_out_ready)

  // ---------------- functional coverage ----------------
  `FC(rd_ID, m_rd && m_map && m_idx == 0)
  `FC(wr_ID, m_wr && m_map && m_idx == 0)
  `FC(rd_IRQ_STATUS, m_rd && m_map && m_idx == 1)
  `FC(wr_IRQ_STATUS, m_wr && m_map && m_idx == 1)
  `FC(rd_IRQ_ENABLE, m_rd && m_map && m_idx == 2)
